-- Generated by `make contracts` from contracts/census_county_pop.odcs.yaml. Do not edit: change the contract and regenerate.
-- Types the latest raw load only; every business rule lives in intermediate models.
with raw as (
    select * from {{ source('raw', 'census_county_pop') }}
),

latest as (
    select * from raw where filename = (select max(filename) from raw)
)

select
  "SUMLEV" AS "sumlev",
  "REGION" AS "region",
  "DIVISION" AS "division",
  "STATE" AS "state_fips",
  "COUNTY" AS "county_fips",
  "STNAME" AS "state_name",
  "CTYNAME" AS "county_name",
  CASE WHEN CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("YEAR"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('year: a value has a fraction, so it isn''t a whole count; check the contract') END AS "year",
  CASE WHEN CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6)) IS NULL THEN NULL WHEN CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6)) = trunc(CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6))) THEN CAST(CAST(NULLIF(trim("POPESTIMATE"), '') AS DECIMAL(38, 6)) AS BIGINT) ELSE error('population: a value has a fraction, so it isn''t a whole count; check the contract') END AS "population"
from latest
